insert into characters (id, is_player, is_secondary, data) values ('moi', true, false, $json${"id":"moi","sprite":"assets/Personnages/Perso principal.png","customizable":true,"defaultName":"Sucrette"}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('isaac', false, false, $json${"id":"isaac","name":"Isaac","tagline":"Le garçon que tout le monde juge avant de le connaître.","age":19,"field":"L1 Information-Communication","height":"1m80","personality":["sarcastique","observateur","protecteur","extrêmement loyal","rancunier","têtu"],"likes":["Les gens honnêtes","Les discussions profondes","Le calme","Les balades de nuit","Les motos anciennes","Les chats"],"dislikes":["Les personnes superficielles","Les mensonges","Les gens qui promettent sans agir"],"routeTheme":"L'abandon. Comment apprendre à faire confiance quand quelqu'un est déjà parti une fois.","goal":"Trouver un métier qui ait du sens, plutôt qu'un métier prestigieux.","passion":"Les motos, le bricolage, les balades de nuit et les chats.","flaw":"Il repousse les personnes qui commencent à compter pour lui, par peur d'être abandonné à son tour.","favoritePlace":"Le toit de la résidence.","sprite":"assets/Personnages/Crushs/PNG/Isaac.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Isaac.png"},"gauges":{"amitie":0,"amour":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('aaron', false, false, $json${"id":"aaron","name":"Aaron","tagline":"Le géant qui fait peur à tout le monde.","age":20,"field":"L1 com","height":"1m92","personality":["très calme","ne se met jamais en colère","attentif aux autres"],"likes":["Le rock","La randonnée","Les chiens","Les vieux films","Le café"],"dislikes":["La violence gratuite","Les gens qui parlent fort","Les disputes"],"routeTheme":"Le deuil.","goal":"Ouvrir un studio de tatouage.","passion":"Le tatouage, le rock, la randonnée, la cuisine et les chiens.","flaw":"Il garde tout pour lui et refuse presque systématiquement qu'on l'aide.","favoritePlace":"La salle de sport, où il évacue son stress en silence.","sprite":"assets/Personnages/Crushs/PNG/Aaron.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Aaron.png"},"gauges":{"amitie":0,"amour":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('sasha', false, false, $json${"id":"sasha","name":"Sasha","tagline":"La personne qui fait rire tout le monde.","age":19,"field":"L1 com","height":"1m78","personality":["drôle","impulsif","créatif","très tactile","immature parfois"],"likes":["Les jeux vidéo","Les concerts","Le skate","Les soirées","La musique"],"dislikes":["Le silence","La solitude"],"routeTheme":"La solitude derrière l'humour.","goal":"Vivre de la création de contenu ou de l'événementiel.","passion":"Les jeux vidéo, les concerts, le skate, les soirées et la musique.","flaw":"Il transforme tout en blague et évite les discussions sérieuses.","favoritePlace":"La cafétéria.","sprite":"assets/Personnages/Crushs/PNG/Sasha.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Sasha.png"},"gauges":{"amitie":0,"amour":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('camel', false, false, $json${"id":"camel","name":"Camel","tagline":"Le garçon qui séduit tout le monde sans jamais s'attacher.","age":19,"field":"L1 dev","height":"1m85","personality":["très sociable","confiant","flatteur","passionné de guitare","très cultivé musicalement"],"likes":["La guitare électrique","Les jeux vidéo narratifs","Les vinyles","La composition"],"dislikes":["Dépendre de quelqu'un","S'engager"],"routeTheme":"La peur de l'engagement.","goal":"Composer des musiques pour le cinéma et les jeux vidéo.","passion":"La guitare électrique, les jeux vidéo narratifs, les vinyles et la composition.","flaw":"Il séduit facilement mais coupe court aux relations dès qu'elles deviennent trop sérieuses.","favoritePlace":"Sa chambre, où il passe des heures à composer seul.","sprite":"assets/Personnages/Crushs/PNG/Camel.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Camel.png"},"gauges":{"amitie":0,"amour":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('mehdi', false, false, $json${"id":"mehdi","name":"Mehdi","tagline":"Le rayon de soleil.","age":19,"field":"L1 Information-Communication","height":"1m80","personality":["toujours souriant","optimiste","sociable","créatif","spontané"],"likes":["La photographie","Les couchers de soleil","Le basket","Les repas en famille","Les voyages improvisés"],"dislikes":["Décevoir les gens","Les conflits","Voir quelqu'un souffrir sans pouvoir l'aider"],"routeTheme":"Le poids des responsabilités et la santé mentale.","goal":"Créer sa propre agence de photographie et voyager pour raconter des histoires humaines.","passion":"La photographie, les voyages, le basket et les couchers de soleil.","flaw":"Il ne sait pas demander de l'aide et s'oublie constamment au profit des autres.","favoritePlace":"Le terrain de basket derrière le campus.","sprite":"assets/Personnages/Crushs/PNG/Mehdi.png","spriteAlt":"assets/Personnages/Crushs/PNG/Mehdi sans veste.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Mehdi.png","sansVeste":"assets/Personnages/Crushs/PNG/Mehdi sans veste.png"},"gauges":{"amitie":0,"amour":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('stella', false, false, $json${"id":"stella","name":"Stella","tagline":"La fille que tout le monde admire.","age":20,"field":"L1 commerce","height":"1m72","personality":["ambitieuse","perfectionniste","très organisée","directe","exigeante","profondément loyale"],"likes":["Les défis","Les musées","La mode","Les débats","Les personnes franches"],"dislikes":["Les préjugés","Les faux-semblants","Qu'on décide à sa place","Perdre son temps"],"routeTheme":"L'acceptation de soi et le besoin de reconnaissance.","goal":"Créer sa propre entreprise et devenir une entrepreneuse reconnue.","passion":"L'entrepreneuriat, la mode, les musées, les débats et la stratégie.","flaw":"Elle est tellement perfectionniste qu'elle peut devenir cassante sans s'en rendre compte.","favoritePlace":"La bibliothèque.","sprite":"assets/Personnages/Crushs/PNG/Stella.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Stella.png"},"gauges":{"amitie":0,"amour":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('liam', false, false, $json${"id":"liam","name":"Liam","tagline":"L'homme que personne ne connaît vraiment.","age":21,"field":"L2 com","height":"1m86","personality":["très mature","très calme","très observateur","parle peu","toujours juste"],"likes":["La littérature","Les vieux appareils photo argentiques","L'histoire","Les promenades matinales"],"dislikes":["L'injustice","Le bruit","Les promesses qu'on ne tient pas"],"routeTheme":"Les aidants familiaux.","goal":"Devenir enseignant-chercheur à l'université.","passion":"La littérature, les vieux appareils photo argentiques, l'histoire et les promenades matinales.","flaw":"Il porte toutes les responsabilités seul et refuse de montrer la moindre faiblesse.","favoritePlace":"Le hall principal du campus, ou la bibliothèque tôt le matin.","sprite":"assets/Personnages/Crushs/PNG/Liam.png","portraits":{"default":"assets/Personnages/Crushs/PNG/Liam.png"},"gauges":{"amitie":0,"amour":0},"stagePosition":"center"}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('leonie', false, true, $json${"id":"leonie","name":"Léonie","tagline":"Les apparences sont parfois très trompeuses.","personality":["extravertie","drôle","spontanée"],"likes":["Les concerts","Le maquillage","Halloween","Les films d'horreur","Les chats"],"dislikes":["Les araignées","Les personnes qui jugent au premier regard","Les conflits"],"routeTheme":"Les préjugés et l'apparence.","goal":"Ouvrir son propre salon de tatouage artistique.","flaw":"Elle réfléchit après avoir parlé.","favoritePlace":"Sa chambre, qui devient rapidement le QG du groupe.","role":"Colocataire du perso principal, future meilleure amie.","sprite":"assets/Personnages/Persos secondaires/PNG/Léonie.png","portraits":{"default":"assets/Personnages/Persos secondaires/PNG/Léonie.png"},"gauges":{"amitie":0},"stagePosition":"left"}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('zoe', false, true, $json${"id":"zoe","name":"Zoé","personality":["énergique","sociable","optimiste","bavarde"],"likes":["Les soirées","Les potins","Les cafés","Organiser des sorties"],"dislikes":["Les silences gênants","Les gens qui restent dans leur coin"],"routeTheme":"Le besoin d'appartenir à un groupe.","goal":"Travailler dans l'événementiel ou les relations publiques.","flaw":"Elle est incapable de garder un secret.","favoritePlace":"La cafétéria.","role":"Connaît absolument tout le monde sur le campus.","sprite":"assets/Personnages/Persos secondaires/PNG/Zoé.png","portraits":{"default":"assets/Personnages/Persos secondaires/PNG/Zoé.png"},"gauges":{"amitie":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('victoria', false, true, $json${"id":"victoria","name":"Victoria","tagline":"La rivale.","personality":["intelligente","ambitieuse","perfectionniste","très sûre d'elle"],"likes":["Les débats","Les défis","Gagner"],"dislikes":["L'improvisation","Perdre","Qu'on la sous-estime"],"routeTheme":"Le perfectionnisme et la comparaison permanente.","goal":"Diriger une grande entreprise ou une agence de communication.","flaw":"Elle manque énormément de tact.","favoritePlace":"La bibliothèque.","role":"Rivale de l'héroïne au début, finit par devenir une alliée.","sprite":"assets/Personnages/Persos secondaires/PNG/Victoria.png","portraits":{"default":"assets/Personnages/Persos secondaires/PNG/Victoria.png"},"gauges":{"amitie":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('nathan', false, true, $json${"id":"nathan","name":"Nathan","personality":["timide","poli","serviable","un peu maladroit socialement"],"likes":["Les jeux vidéo","La programmation","Les puzzles","Les mangas"],"dislikes":["Les conflits","Parler devant un groupe","Être le centre de l'attention"],"routeTheme":"Le manque de confiance en soi.","goal":"Créer son propre studio de développement de jeux vidéo.","flaw":"Il dit toujours \"oui\", même lorsqu'il n'en a pas envie.","favoritePlace":"Coin informatique de la bibliothèque.","role":"Le geek timide, se fait bully mais devient rapidement ami avec l'héroïne.","sprite":"assets/Personnages/Persos secondaires/PNG/Nathan.png","portraits":{"default":"assets/Personnages/Persos secondaires/PNG/Nathan.png"},"gauges":{"amitie":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
insert into characters (id, is_player, is_secondary, data) values ('charlie', false, true, $json${"id":"charlie","name":"Charlie","tagline":"La mythomane.","age":19,"field":"L1 com","height":"1m60","personality":["calme","imaginative","toujours souriante","mythomane"],"likes":["Écrire des histoires","Observer les gens","Imaginer la vie des inconnus"],"dislikes":["Qu'on lui demande de parler sérieusement d'elle-même"],"routeTheme":"Réapprendre à être elle-même sans avoir besoin de s'inventer une autre vie.","flaw":"Mélange réalité et fiction, source de ragots incertains.","role":"Transmet des informations (vraies, déformées ou fausses) sur les autres étudiants.","sprite":"assets/Personnages/Persos secondaires/PNG/Charlie.png","portraits":{"default":"assets/Personnages/Persos secondaires/PNG/Charlie.png"},"gauges":{"amitie":0}}$json$::jsonb) on conflict (id) do update set is_player = excluded.is_player, is_secondary = excluded.is_secondary, data = excluded.data;
